import logging
from ute_common_abstract_core.aliases_registry import aliases_registry
from ute_common_abstract_core.config import Config


class UteUeConfig(object):
    """
    Class containing additional common keywords related to UTE UE configuration
    UTE UE configuration is taken from Singleton ute_common_abstract_core.config.Config
    !!! Remember to use KWs after "Require UE" !!!
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    ue_config_storage = {}

    def __init__(self):
        self.__abstract_config = None
        self.__abstract_config_dict = None
        self.__abstract_config_path = None

    @property
    def abstract_config(self):
        """
        Gets abstract config variable
        """
        if not self.__abstract_config:
            self.__abstract_config = Config()
        return self.__abstract_config

    @property
    def abstract_config_dict(self):
        """
        Gets abstract config dictionary variable
        """
        if not self.__abstract_config_dict:
            self.__abstract_config_dict = self.abstract_config.get_config()
        return self.__abstract_config_dict

    @property
    def abstract_config_path(self):
        """
        abstract config path variable getter
        """
        if not self.__abstract_config_path:
            self.__abstract_config_path = self.abstract_config.get_config_path()
        return self.__abstract_config_path

    @staticmethod
    def _warn_that_yaml_is_not_used():
        """
        Static method warning if UE YAML is not used
        """
        msg = "UTE UE configuration path is empty, most probably YAML file is not used for UTE UEs definition"
        logging.warn(msg)

    def _find_ue_config(self, ue_alias):
        """
        Finds ue config that fits ue given in ue_alias parameter

        :param ue_alias:
        """
        ute_ue = aliases_registry()[ue_alias]
        ue_pools = self.abstract_config_dict['UE_POOLS']
        chosen_ue_config = {}
        for ue_pool in ue_pools.values():
            inline_configs = ue_pool['inline_config']
            if ute_ue.name in inline_configs:
                ue_config = inline_configs[ute_ue.name]
                if ue_config['CONSTRUCTOR_PARAMETERS']['serial_number'] == ute_ue.ue_id:
                    chosen_ue_config = ue_config
                    break
        return chosen_ue_config

    def _get_ue_configuration(self, ue_alias):
        """
        Gets UE configuration if exists in storage or calls '_find_ue_config' to find for given UE

        :param ue_alias:
        """
        ue_config = self.ue_config_storage.get(ue_alias)
        if ue_config is None:
            ue_config = self._find_ue_config(ue_alias)
            self.ue_config_storage[ue_alias] = ue_config
        return ue_config

    def get_from_ute_ue_config(self, ue_alias, top_level_key):
        """
        Gets parameter specified in in 'top_level_key' for UE given in 'ue_alias from UE YAML'

        :param ue_alias:
        :param top_level_key:
        """
        ute_ue = aliases_registry()[ue_alias]
        logging.debug("UTE UE name : {}".format(ute_ue.name))
        if self.abstract_config_dict:
            ue_config = self._get_ue_configuration(ue_alias)
            return ue_config[top_level_key]

    def get_ute_ue_configuration_dict(self):
        """
        Gets ute_ue configuration from UE YAML in dictionary format
        """
        logging.debug("Config path: {}".format(self.abstract_config_path))
        return self.abstract_config_dict

    def get_from_ute_ue_config_yaml(self, ue_alias, top_level_key):
        """
        Gets parameter specified in in 'top_level_key' for UE given in 'ue_alias from UE YAML'

        :param ue_alias:
        :param top_level_key:
        """
        if not self.abstract_config_path:
            self._warn_that_yaml_is_not_used()
        else:
            return self.get_from_ute_ue_config(ue_alias, top_level_key)

    def get_4g_starting_cell_id_for(self, ue_alias):
        """
        Gets 'STARTING_CELL' parameter for given 'ue_alias' from UE YAML

        :param ue_alias:
        """
        return self.get_from_ute_ue_config_yaml(ue_alias=ue_alias,
                                                top_level_key="STARTING_CELL")

    def get_5g_starting_cell_id_for(self, ue_alias):
        """
        Gets 'STARTING_CELL_5G_ID' parameter for given 'ue_alias' from UE YAML

        :param ue_alias:
        """
        return self.get_from_ute_ue_config_yaml(ue_alias=ue_alias,
                                                top_level_key="STARTING_CELL_5G_ID")

    def get_5g_starting_cell_pci_for(self, ue_alias):
        """
        Gets 'STARTING_CELL_5G_PCI' parameter for given 'ue_alias' from UE YAML

        :param ue_alias:
        """
        return self.get_from_ute_ue_config_yaml(ue_alias=ue_alias,
                                                top_level_key="STARTING_CELL_5G_PCI")
